const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'Rs. '+Number(n).toLocaleString('en-LK'),today=()=>new Date().toLocaleDateString('en-CA');
const db={products:[{id:'P001',name:'Classic butter croissant',category:'Pastries',price:450,description:'Golden layers. A buttery little escape.',availability:'Available',image:'croissant.jpg',tag:'Bestseller',quantity:18,manualSoldOut:false},{id:'P002',name:'Chocolate celebration cake',category:'Cakes',price:4200,description:'Rich chocolate, made for sharing.',availability:'Available',image:'chocolate-cake.webp',tag:'For the occasion',quantity:4,manualSoldOut:false},{id:'P003',name:'Artisan sourdough',category:'Bread',price:950,description:'A crisp crust and a beautifully soft centre.',availability:'Available',image:'artisan-bread.webp',tag:'Freshly baked',quantity:10,manualSoldOut:false},{id:'P004',name:'Croissant sharing box',category:'Pastries',price:2500,description:'Six buttery favourites, one happy table.',availability:'Available',image:'croissant.jpg',tag:'Box of 6',quantity:6,manualSoldOut:false}],customers:[{id:'C001',name:'Alex Perera',email:'alex@example.com',phone:'077 123 4567',address:'24 Flower Road, Colombo',type:'Regular',role:'CUSTOMER'}],cakes:[],orders:[],bookings:[],payments:[],reviews:[]};
let cart=[],category='All bakes',query='',adminTab='products',adminQuery='',signedIn=false,currentRole='GUEST',sessionUser=null,seq=100;
const adminAccounts=[{id:'A001',name:'Crumb Owner',email:'admin@crumb.lk',password:'admin123',role:'ADMIN'}];
const profile=()=>db.customers[0];
const currentUser=()=>sessionUser||(currentRole==='CUSTOMER'?profile():null);
const isAdmin=()=>currentRole==='ADMIN';
const images={Cakes:'chocolate-cake.webp',Bread:'artisan-bread.webp',Pastries:'croissant.jpg'};
const productStock=p=>Math.max(0,Number(p?.quantity??0));
const productIsSoldOut=p=>!p||p.manualSoldOut===true||p.availability==='Sold out'||productStock(p)<=0;
const productStockLabel=p=>productIsSoldOut(p)?'Sold out':productStock(p)<=3?`${productStock(p)} left`:'Available';
const cartCanIncrease=c=>{const p=db.products.find(p=>p.id===c.id);return !p||productIsSoldOut(p)||c.qty>=productStock(p)};
function id(prefix){return prefix+(++seq)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(content){$('#dialog').classList.remove('auth-glass');$('#dialog').removeAttribute('aria-labelledby');$('#dialog-body').innerHTML=content;$('#dialog').showModal()}
function closeModal(){$('#dialog').close()}
function title(k,h,p=''){return `<div class="page-head"><span class="eyebrow">${k}</span><h1>${h}</h1>${p?`<p class="muted">${p}</p>`:''}</div>`}
function empty(h,p,href='#shop',label='Explore the bakery'){return `<div class="empty"><h3>${h}</h3><p class="muted">${p}</p><a class="btn" href="${href}">${label} →</a></div>`}
function badge(status){return `<span class="status ${status==='Cancelled'?'cancelled':''}">${esc(status)}</span>`}
function input(label,name,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''} ${type==='date'?`min="${new Date().toISOString().slice(0,10)}"`:''}></label>`}
function select(label,name,values,current=''){return `<label>${label}<select name="${name}">${values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function area(label,name,value=''){return `<label class="wide">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function totals(){const sub=cart.reduce((n,c)=>n+c.price*c.qty,0);return{sub,total:sub}}
function addToCart(pid){const p=db.products.find(p=>p.id===pid);if(!p||productIsSoldOut(p)){toast(`${p?.name||'This bake'} is sold out`);throw Error('Product is sold out')}const existing=cart.find(c=>c.id===pid);if(existing&&existing.qty>=productStock(p)){toast(`Only ${productStock(p)} available`);return {productId:pid,quantity:existing.qty}}existing?existing.qty++:cart.push({...p,qty:1});$('#cart-count').textContent=cart.reduce((n,c)=>n+c.qty,0);toast(p.name+' added to your bag');return {productId:pid,quantity:cart.find(c=>c.id===pid).qty}}
function changeQty(pid,delta){const c=cart.find(c=>c.id===pid);if(!c)return;if(delta>0&&cartCanIncrease(c)){toast(productIsSoldOut(db.products.find(p=>p.id===pid))?'This bake is sold out':`Only ${productStock(db.products.find(p=>p.id===pid))} available`);return}c.qty+=delta;if(c.qty<=0)cart=cart.filter(c=>c.id!==pid);render()}
function productCards(){const list=db.products.filter(p=>(category==='All bakes'||p.category===category)&&`${p.name} ${p.description} ${p.id}`.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(p=>{const sold=productIsSoldOut(p),label=productStockLabel(p);return `<article class="product ${sold?'sold-out-product':''}"><div class="product-image"><img src="${esc(p.image||images[p.category]||images.Bread)}" alt="${esc(p.name)}" loading="lazy"><span class="tag">${esc(sold?'Sold out':p.tag||p.category)}</span><button class="add" aria-label="Add ${esc(p.name)} to bag" onclick="addToCart('${p.id}')" ${sold?'disabled':''}>+</button></div><h3>${esc(p.name)}</h3><p class="desc">${esc(p.description)}</p><div class="price-row"><strong>${money(p.price)}</strong><span class="${sold?'stock-sold-out':productStock(p)<=3?'stock-low':''}">${label}</span></div></article>`}).join(''):empty('No bakes found','Try another name or category.');}
function shop(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Small batches. Big moments.</span><h1>Your daily dose<br>of <em>something good.</em></h1><p>Flaky mornings, sweet celebrations, and everything in between. Find your next favourite bake.</p><a class="btn" href="#bakes" onclick="event.preventDefault();document.querySelector('#bakes').scrollIntoView({behavior:'smooth'})">Explore the bakes <span>↗</span></a></div><div class="hero-image"><img src="../croissant.jpg" alt="Fresh golden croissant served on a ceramic plate" style="object-position:center 62%"><span class="image-label">BUTTER MAKES IT BETTER.</span></div></section><section class="section" id="bakes"><div class="section-head"><div><span class="eyebrow">From our oven</span><h2>A little something for everyone.</h2></div><a class="text-link" href="#reviews">Customer reviews ↗</a></div><div class="toolbar"><div class="chips">${['All bakes', 'Bread', 'Pastries', 'Cakes'].map(c => `<button class="chip ${c === category ? 'active' : ''}" onclick="category='${c}';render();document.querySelector('#bakes').scrollIntoView()">${c}</button>`).join('')}</div><input class="search" aria-label="Search bakery products" placeholder="Search your favourite bake…" value="${esc(query)}" oninput="query=this.value;document.querySelector('#products').innerHTML=productCards()"></div><div class="catalog" id="products">${productCards()}</div><div class="cake-banner"><div><span class="eyebrow">Your moment. Your cake.</span><h2>A celebration with your name on it.</h2><p>Choose the flavour, the finishing touches, and the words that matter.</p></div><a href="#cakes" class="btn">Create your cake ↗</a></div></section>`}
function cakePage(){return title('The cake studio','Make it a little more you.','A birthday, a big day, or just because. Let’s make something special.')+`<section class="section two-col"><form class="panel" id="cake-form" onsubmit="submitCake(event)"><h3>Start with the good stuff</h3><p class="muted">Design your cake and choose when you need it.</p><div class="form-grid">${select('Occasion','occasion',['Birthday','Wedding','Celebration'])}${select('Cake size','size',['1 kg · 8–10 servings','2 kg · 16–20 servings','3 kg · 24–30 servings'])}${select('Flavour','flavour',['Chocolate','Vanilla','Red velvet','Coffee'])}${select('Toppings','toppings',['Chocolate curls','Fresh fruit','Buttercream flowers','No toppings'])}${input('Date needed','date','','date')}${select('Collection method','method',['Pickup','Delivery'])}${input('Message on cake','message','Happy Birthday!','text',false)}${input('Delivery address (if delivery)','address',profile()?.address||'','text',false)}${area('Design ideas & special instructions','design')}</div><div class="form-actions"><button class="btn">Request this cake →</button></div><p class="muted" style="font-size:12px">Demo request only. The bakery would confirm the design and final price.</p></form><aside class="panel"><img class="summary-img" src="chocolate-cake.webp" alt="Chocolate celebration cake"><span class="eyebrow" style="display:block;margin-top:24px">Made for your moment</span><h2>Your celebration, beautifully baked.</h2><div class="summary-line"><span>Base cake · 1 kg</span><strong>${money(4200)}</strong></div><div class="summary-line"><span>Each additional kg</span><strong>${money(3000)}</strong></div><div class="summary-line"><span>Delivery, if selected</span><strong>${money(350)}</strong></div><p class="note">The photo is inspiration. Custom designs are subject to bakery confirmation. Your request will appear in Bookings.</p></aside></section>`}
function submitCake(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.method==='Delivery'&&!d.address.trim()){toast('Please add a delivery address');return}if(d.date<new Date().toISOString().slice(0,10)){toast('Choose today or a future date');return}const cake={...d,id:id('CK'),customer:'C001',status:'Requested',price:4200+(parseInt(d.size)-1)*3000};db.cakes.push(cake);db.bookings.push({id:id('BK'),customer:'C001',item:`${d.occasion} cake · ${d.flavour}`,cakeId:cake.id,date:d.date,method:d.method,address:d.address,instructions:d.design,status:'Requested',total:cake.price+(d.method==='Delivery'?350:0)});location.hash='bookings';toast('Your cake request has been created')}
function cartPage(){return title('Fresh picks','Your bag',cart.length?'Good choices. Let’s make them yours.':'A little room for something delicious.')+`<section class="section">${cart.length?`<div class="two-col"><div class="panel">${cart.map(c=>`<div class="cart-item"><img src="${esc(c.image)}" alt="${esc(c.name)}"><div><h3>${esc(c.name)}</h3><div class="qty-info">${money(c.price)} each</div></div><div class="quantity"><button aria-label="Remove one ${esc(c.name)}" onclick="changeQty('${c.id}',-1)">−</button><span>${c.qty}</span><button aria-label="Add one ${esc(c.name)}" onclick="changeQty('${c.id}',1)" ${cartCanIncrease(c)?'disabled':''}>+</button></div><strong>${money(c.price*c.qty)}</strong></div>`).join('')}<div class="form-actions"><a class="text-link" href="#shop">← Keep browsing</a></div></div><form class="panel" onsubmit="placeOrder(event)"><h3>Order summary</h3><div class="summary-line"><span>Subtotal</span><strong>${money(totals().sub)}</strong></div><div class="form-grid" style="margin-top:20px">${select('Fulfilment','method',['Pickup','Delivery'])}${input('Requested date','date','','date')}${input('Name','name',profile()?.name||'')}${input('Phone number','phone',profile()?.phone||'','tel')}${area('Delivery address (required for delivery)','address',profile()?.address||'')}${select('Payment option','payment',['Cash on pickup / delivery','Card payment demo'])}</div><div class="summary-line total"><span>Total</span><strong id="checkout-total">${money(totals().sub)}</strong></div><p class="note">Delivery adds Rs. 350. Card demo records a simulated payment; no card details or money are collected.</p><button class="btn" style="width:100%;margin-top:15px">Place demo order →</button></form></div>`:empty('Your bag is waiting','Add a fresh bake to get started.')}</section>`}
function placeOrder(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!cart.length)return;if(d.method==='Delivery'&&!d.address.trim()){toast('A delivery address is required');return}const unavailable=cart.find(c=>{const p=db.products.find(p=>p.id===c.id);return productIsSoldOut(p)||c.qty>productStock(p)});if(unavailable){toast(`${unavailable.name} no longer has enough stock`);render();return}const order={...d,id:id('OR'),customer:'C001',date:d.date,items:cart.map(c=>({...c})),total:totals().sub+(d.method==='Delivery'?350:0),status:'Confirmed'};cart.forEach(c=>{const p=db.products.find(p=>p.id===c.id);p.quantity=Math.max(0,productStock(p)-c.qty);if(p.quantity===0)p.availability='Sold out'});db.orders.push(order);db.bookings.push({id:id('BK'),customer:'C001',item:`Bakery order ${order.id}`,orderId:order.id,date:d.date,method:d.method,address:d.address,instructions:'',total:order.total,status:'Confirmed'});db.payments.push({id:id('PAY'),order:order.id,amount:order.total,method:d.payment,date:new Date().toISOString().slice(0,10),status:d.payment.startsWith('Card')?'Simulated paid':'Pending'});cart=[];location.hash='orders';toast('Demo order placed. Your fresh picks are booked!')}
function ordersPage(){return title('Your bakery diary','My orders','Follow your orders from our oven to your table.')+`<section class="section">${db.orders.length?db.orders.map(o=>`<article class="record"><div class="record-top"><div><span class="eyebrow">${o.id}</span><h3>${o.items.map(c=>`${c.qty} × ${esc(c.name)}`).join(', ')}</h3></div>${badge(o.status)}</div><div class="record-meta"><span>${esc(o.date)}</span><span>${esc(o.method)}</span><strong>${money(o.total)}</strong></div><div class="record-actions"><button class="btn secondary" onclick="orderDetails('${o.id}')">Order & payment details</button>${!['Cancelled','Completed'].includes(o.status)?`<button class="btn secondary" onclick="editOrder('${o.id}')">Edit order</button><button class="btn secondary" onclick="cancelRecord('orders','${o.id}')">Cancel order</button>`:''}${o.status==='Completed'?`<button class="btn" onclick="reviewForm(null,'${o.id}')">Write a review</button>`:''}</div></article>`).join(''):empty('No orders just yet','Your next favourite bake is one click away.')}</section>`}
function orderDetails(oid){const o=db.orders.find(x=>x.id===oid),p=db.payments.find(x=>x.order===oid);modal(`<span class="eyebrow">Order ${o.id}</span><h2>Your order details</h2>${o.items.map(c=>`<div class="summary-line"><span>${c.qty} × ${esc(c.name)}</span><strong>${money(c.price*c.qty)}</strong></div>`).join('')}<div class="summary-line"><span>${esc(o.method)} · ${esc(o.date)}</span><span>${o.method==='Delivery'?money(350):'Free pickup'}</span></div><p>${esc(o.address||'Pickup at the bakery')}</p>${o.adminFeedback?`<p class="note admin-feedback"><strong>Note from Crumb</strong><br>${esc(o.adminFeedback)}</p>`:''}<div class="summary-line total"><span>Total</span><strong>${money(o.total)}</strong></div><h3>Payment record</h3><p>${p?`${esc(p.id)} · ${esc(p.method)}<br>${badge(p.status)}`:'No payment record available'}</p>`)}
function editOrder(oid){const o=db.orders.find(x=>x.id===oid);modal(`<h2>Edit ${oid}</h2><form onsubmit="saveOrder(event,'${oid}')"><div class="form-grid">${input('Requested date','date',o.date,'date')}${select('Method','method',['Pickup','Delivery'],o.method)}${area('Delivery address','address',o.address)}${o.items.map(c=>input(c.name,`qty_${c.id}`,c.qty,'number')).join('')}</div><div class="form-actions"><button class="btn">Save order</button></div></form>`)}
function saveOrder(e,oid){e.preventDefault();const o=db.orders.find(x=>x.id===oid),d=Object.fromEntries(new FormData(e.target));if(d.method==='Delivery'&&!d.address.trim()){toast('Add a delivery address');return}const items=o.items.map(c=>({...c,qty:Number(d['qty_'+c.id])})).filter(c=>c.qty>0);if(!items.length){toast('Keep at least one item, or cancel the order');return}Object.assign(o,{items,date:d.date,address:d.address,method:d.method,total:items.reduce((n,c)=>n+c.qty*c.price,0)+(d.method==='Delivery'?350:0)});db.bookings.filter(b=>b.orderId===oid).forEach(b=>Object.assign(b,{date:o.date,address:o.address,method:o.method,total:o.total}));db.payments.filter(p=>p.order===oid).forEach(p=>p.amount=o.total);closeModal();render();toast('Order updated')}
function bookingsPage(){return title('Something to look forward to','My bookings','Manage your custom cakes, pickup times, and deliveries.')+`<section class="section">${db.bookings.length?db.bookings.map(b=>`<article class="record"><div class="record-top"><div><span class="eyebrow">${b.id}</span><h3>${esc(b.item)}</h3></div>${badge(b.status)}</div><div class="record-meta"><span>${esc(b.date)}</span><span>${esc(b.method)}</span><span>${b.method==='Delivery'?esc(b.address):'Collect from the bakery'}</span><strong>${money(b.total)}</strong></div><div class="record-actions"><button class="btn secondary" onclick="bookingDetails('${b.id}')">View details</button>${!['Cancelled','Completed'].includes(b.status)?`<button class="btn secondary" onclick="bookingEdit('${b.id}')">Edit booking</button>${b.cakeId?`<button class="btn secondary" onclick="editEntity('cakes','${b.cakeId}')">Edit cake</button>`:''}<button class="btn secondary" onclick="cancelRecord('bookings','${b.id}')">Cancel booking</button>`:''}</div></article>`).join(''):empty('Your calendar has room for cake','Create a custom cake or place an order to make a booking.','#cakes','Create a cake')}</section>`}
function bookingDetails(bid){const b=db.bookings.find(x=>x.id===bid),c=db.cakes.find(x=>x.id===b.cakeId);modal(`<span class="eyebrow">${b.id}</span><h2>${esc(b.item)}</h2><p>${esc(b.date)} · ${esc(b.method)}</p>${badge(b.status)}${c?`<div class="summary-line"><span>Size & flavour</span><strong>${esc(c.size)} · ${esc(c.flavour)}</strong></div><div class="summary-line"><span>Toppings</span><span>${esc(c.toppings)}</span></div><p>Message: ${esc(c.message||'None')}</p><p>Design: ${esc(c.design||'No special design requested')}</p>`:''}<p>${esc(b.instructions||'No additional instructions.')}</p><p>${esc(b.address||'Pickup from the bakery')}</p><div class="summary-line total"><span>Estimated total</span><strong>${money(b.total)}</strong></div>`)}
function bookingEdit(bid){editEntity('bookings',bid)}
function cancelRecord(type,rid){modal(`<h2>Cancel this ${type==='orders'?'order':'booking'}?</h2><p>This will also cancel its linked ${type==='orders'?'booking':'order or cake request'}.</p><div class="form-actions"><button class="btn danger" onclick="confirmCancel('${type}','${rid}')">Confirm cancellation</button><button class="btn secondary" onclick="closeModal()">Keep it</button></div>`)}
function confirmCancel(type,rid){const r=db[type].find(x=>x.id===rid);if(!r)return;if(type==='orders'&&r.status!=='Cancelled'&&!r.stockRestored){r.items?.forEach(item=>{const p=db.products.find(p=>p.id===item.id);if(p){p.quantity=productStock(p)+Number(item.qty||0);if(!p.manualSoldOut)p.availability='Available'}});r.stockRestored=true}r.status='Cancelled';const oid=type==='orders'?rid:r.orderId;db.bookings.filter(b=>(oid&&b.orderId===oid)||b.id===rid).forEach(b=>{b.status='Cancelled';if(b.cakeId){const c=db.cakes.find(x=>x.id===b.cakeId);if(c)c.status='Cancelled'}});db.orders.filter(o=>o.id===oid).forEach(o=>o.status='Cancelled');db.payments.filter(p=>p.order===oid).forEach(p=>p.status=p.status==='Pending'?'Cancelled':'Refund pending (demo)');closeModal();render();toast('Cancellation saved')}
function accountPage(){if(!signedIn)return accountWelcome();const p=currentUser()||profile();if(!p)return title('Welcome to Crumb','Your account')+`<section class="section"><button class="btn" onclick="authForm('register')">Create an account</button></section>`;return title('Your little corner','My account','Keep your details ready for your next order.')+`<section class="section two-col"><form class="panel" onsubmit="saveProfile(event)"><h3>Personal details</h3><div class="form-grid" style="margin-top:24px">${input('Full name','name',p.name)}${input('Email address','email',p.email,'email')}${input('Phone number','phone',p.phone||'','tel')}${select('Customer type','type',['Regular','Premium'],p.type||p.customerType||'Regular')}${area('Delivery address','address',p.address||'')}</div><div class="form-actions"><button class="btn">Save details</button><button type="button" class="btn secondary" onclick="authForm('password')">Change password</button></div></form><aside class="panel"><span class="eyebrow">${signedIn?'Active Account':'Account'}</span><h2>Hello, ${esc(p.name.split(' ')[0])}.</h2><div class="form-actions" style="margin-top:24px"><button class="btn secondary" onclick="signOut()">Sign out</button></div><hr style="border:0;border-top:1px solid var(--line);margin:30px 0"><button class="text-link" style="background:none;border:0;color:#a34336" onclick="deleteCustomerAccount('${p.id}')">Delete customer profile</button></aside></section>`}
async function saveProfile(e){
  e.preventDefault();
  const d=Object.fromEntries(new FormData(e.target));
  const user=currentUser()||profile();
  if(user?.id){
    try{
      const res=await fetch('/api/users/'+encodeURIComponent(user.id),{
        method:'PUT',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({name:d.name,email:d.email,phone:d.phone,address:d.address,customerType:d.type})
      });
      const data=await res.json();
      if(data.success&&data.data){
        Object.assign(user,{...data.data,type:data.data.customerType||d.type});
      }
    }catch(_){}
  }
  Object.assign(profile(),d);
  toast('Profile updated');
  render();
}
function updateAuthHeader(){const el=$('#auth-actions'),user=currentUser()||profile();if(!el)return;el.innerHTML=`<button type="button" class="profile-icon" aria-label="${signedIn?(isAdmin()?'Open owner workspace':'Open your account'):'Sign in or sign up'}" aria-haspopup="dialog" title="${signedIn?(isAdmin()?'Owner workspace':'My account'):'Sign in / Sign up'}" onclick="openProfilePopup()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/></svg></button>`;const adminEntry=$('#admin-entry');if(adminEntry)adminEntry.innerHTML=isAdmin()?'<a href="#admin">Owner workspace ↗</a>':''}
function openProfilePopup(){if(!signedIn){authForm('login');return}const user=currentUser()||profile();if(isAdmin()){modal(`<span class="eyebrow">Private owner area</span><h2>${esc(user.name||'Crumb Owner')}</h2><p class="muted">${esc(user.email||'')} · Admin account</p><div class="form-actions"><a class="btn" href="#admin" onclick="closeModal()">Owner dashboard</a><button class="btn secondary" onclick="closeModal();signOut()">Sign out</button></div>`);return}modal(`<span class="eyebrow">Your account</span><h2>Hello, ${esc((user?.name||'Guest').split(' ')[0])}.</h2><p class="muted">${esc(user?.email||'')}</p><div class="form-actions"><a class="btn" href="#account" onclick="closeModal()">My profile</a><a class="btn secondary" href="#orders" onclick="closeModal()">Order history</a><button class="btn secondary" onclick="closeModal();signOut()">Sign out</button></div>`)}
function accountWelcome(){return title('Your little corner','Good to have you here.','A home for your details, favourite moments, and next celebration.')+`<section class="section account-welcome"><div class="panel"><span class="eyebrow">A little more crumb</span><h2>Your next sweet moment starts here.</h2><p class="muted">Sign in to manage your profile, or create an account to get started.</p><div class="form-actions"><button class="btn" onclick="authForm('login')">Sign in →</button><button class="btn secondary" onclick="authForm('register')">Create an account</button></div></div></section>`}
function passwordField(label,name,confirm=false){return `<label class="password-label">${label}<span class="password-input"><input type="password" name="${name}" required minlength="6" autocomplete="off" placeholder="${confirm?'Repeat your password':'At least 6 characters'}"><button type="button" class="password-toggle" aria-label="Show ${confirm?'confirmation':'password'}" aria-pressed="false" onclick="togglePassword(this)">Show</button></span></label>`}
function togglePassword(button){const field=button.parentElement.querySelector('input'),show=field.type==='password';field.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',`${show?'Hide':'Show'} ${field.name==='confirm'?'confirmation':'password'}`)}
function authForm(mode='login'){
  const register=mode==='register',change=mode==='password';
  modal(`<div class="auth-dialog"><span class="eyebrow">${change?'Account settings':'Welcome to crumb'}</span><h2 id="auth-title">${register?'Your seat at the table.':change?'A fresh password.':'Hello again.'}</h2><p class="muted auth-intro">${register?'A few details, and you’re part of the club.':change?'Enter your new password below.':'Sign in for your next little treat.'}</p>${!change?`<div class="auth-tabs" role="group" aria-label="Account options"><button type="button" class="${!register?'selected':''}" aria-pressed="${!register}" onclick="authForm('login')">Sign in</button><button type="button" class="${register?'selected':''}" aria-pressed="${register}" onclick="authForm('register')">Sign up</button></div>`:''}<form class="auth-form" onsubmit="authSubmit(event,'${mode}')"><div class="form-grid">${register?input('Full name','name','','text'):''}${!change?`<label>Email address<input type="email" name="email" required autocomplete="email" placeholder="you@example.com" value="${!register?esc(profile()?.email||'alex@example.com'):''}"></label>`:''}${passwordField(change?'New password':'Password','password')}${register||change?passwordField('Confirm password','confirm',true):''}</div><p id="auth-error" class="auth-error" role="alert"></p><button class="btn auth-submit" type="submit">${register?'Create account':change?'Update password':'Sign in'} <span>→</span></button><p class="auth-footnote">${register?'Already have an account?':'New around here?'} ${!change?`<button type="button" class="inline-auth" onclick="authForm('${register?'login':'register'}')">${register?'Sign in':'Sign up'}</button>`:''}</p><p class="auth-demo-note">${!register&&!change?`<strong>Owner account:</strong> admin@crumb.lk · admin123`:``}</p></form></div>`);
  const dialog=$('#dialog');dialog.classList.add('auth-glass');dialog.setAttribute('aria-labelledby','auth-title');dialog.addEventListener('close',()=>{dialog.classList.remove('auth-glass');dialog.removeAttribute('aria-labelledby')},{once:true});
}
async function authSubmit(e,mode){
 e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),email=(d.email||'').trim().toLowerCase(),error=$('#auth-error');const fail=message=>{if(error)error.textContent=message;else toast(message)};
 if(!d.password||d.password.length<6){fail('Use at least 6 characters.');return}
 if((mode==='register'||mode==='password')&&d.password!==d.confirm){fail('Your passwords do not match. Please try again.');return}
 if(mode!=='password'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){fail('Enter a valid email address.');return}
 if(mode==='register'){
   if(!d.name?.trim()){fail('Please enter your name.');return}
   try{
     const res=await fetch('/api/users/register',{
       method:'POST',
       headers:{'Content-Type':'application/json'},
       body:JSON.stringify({name:d.name.trim(),email,password:d.password,role:'CUSTOMER',customerType:'Regular'})
     });
     const json=await res.json();
     if(!res.ok||!json.success){
       fail(json.message||'Registration failed.');return;
     }
     const p={id:json.data.id,name:json.data.name,email:json.data.email,phone:json.data.phone||'',address:json.data.address||'',type:json.data.customerType||'Regular',role:'CUSTOMER'};
     if(profile())Object.assign(profile(),p);else db.customers.push(p);sessionUser={...p};currentRole='CUSTOMER';signedIn=true;
   }catch(_){
     const p={id:profile()?.id||'C001',name:d.name.trim(),email,phone:'',address:'',type:'Regular',role:'CUSTOMER'};if(profile())Object.assign(profile(),p);else db.customers.push(p);sessionUser={...p};currentRole='CUSTOMER';signedIn=true;
   }
 }else if(mode==='login'){
   try{
     const res=await fetch('/api/users/login',{
       method:'POST',
       headers:{'Content-Type':'application/json'},
       body:JSON.stringify({email,password:d.password})
     });
     const json=await res.json();
     if(!res.ok||!json.success){
       fail(json.message||'Invalid email or password.');return;
     }
     const user=json.data;
     sessionUser={...user,type:user.customerType||'Regular'};
     currentRole=user.role;
     signedIn=true;
     closeModal();
     if(user.role==='ADMIN'){location.hash='admin';toast('Owner workspace unlocked');}
     else{render();toast('Welcome back! Your session is ready.');}
     return;
   }catch(_){
     const admin=adminAccounts.find(a=>a.email===email&&a.password===d.password);
     if(admin){sessionUser={...admin};currentRole='ADMIN';signedIn=true;closeModal();location.hash='admin';render();toast('Owner workspace unlocked');return}
     if(email!==(profile()?.email||'').toLowerCase()){fail('This email has no profile. Choose Sign up to create one.');return}
     sessionUser={...profile(),role:'CUSTOMER'};currentRole='CUSTOMER';signedIn=true;
   }
 }else if(mode==='password'){
   const user=currentUser()||profile();
   if(user?.id){
     try{
       await fetch('/api/users/'+encodeURIComponent(user.id),{
         method:'PUT',
         headers:{'Content-Type':'application/json'},
         body:JSON.stringify({password:d.password})
       });
     }catch(_){}
   }
   signedIn=true;if(!isAdmin()){currentRole='CUSTOMER';sessionUser={...profile(),role:'CUSTOMER'};}
 }
 closeModal();render();toast(mode==='password'?'Password updated successfully':mode==='register'?'Your account is ready. Welcome to Crumb!':'Welcome back! Your session is ready.');
}
function signOut(){signedIn=false;currentRole='GUEST';sessionUser=null;if(location.hash.replace(/^#/,'')==='admin')location.hash='shop';render();toast('You’ve signed out of the demo')}
function contactPage(){return title('A little conversation','Let’s talk cake.','Questions about a bake, a booking, or a special celebration? Start here.')+`<section class="section two-col contact-layout"><form class="panel" onsubmit="previewEnquiry(event)"><h3>Get in touch</h3><p class="muted">Tell us what you have in mind.</p><div class="form-grid">${input('Your name','name',signedIn?profile()?.name||'':'')}${input('Email address','email',signedIn?profile()?.email||'':'','email')}${select('What is it about?','topic',['General enquiry','Bakery order','Custom cake','Pickup or delivery'])}${input('Order or booking ID (optional)','reference','','text',false)}<label class="wide">Your message<textarea name="message" required minlength="10" maxlength="3000" placeholder="A few details will help us understand your enquiry…"></textarea></label></div><p class="note">Frontend demo: you can preview your enquiry here. Messages are not sent; the bakery’s contact service still needs to be connected.</p><button class="btn" type="submit">Preview enquiry <span>→</span></button></form><aside class="contact-aside"><div class="panel"><span class="eyebrow">Already ordered?</span><h3>Your order, at a glance.</h3><p class="muted">Check your order details or manage a pickup or delivery booking.</p><div class="form-actions"><a href="#orders" class="text-link">Order history</a><a href="#bookings" class="text-link">My bookings</a></div></div><div class="panel"><span class="eyebrow">Something worth celebrating</span><h3>Make it your own.</h3><p class="muted">Choose your flavour, finishing touches, and celebration date in the cake studio.</p><a class="text-link" href="#cakes">Create a custom cake ↗</a></div></aside></section>`}
function previewEnquiry(event){event.preventDefault();const d=Object.fromEntries(new FormData(event.target));if(!d.name?.trim()||!d.email?.trim()||!d.message||d.message.trim().length<10){toast('Please add your name, email, and a message of at least 10 characters.');return}modal(`<span class="eyebrow">Enquiry preview · not sent</span><h2>${esc(d.topic)}</h2><div class="summary-line"><span>From</span><strong>${esc(d.name)}</strong></div><div class="summary-line"><span>Email</span><span>${esc(d.email)}</span></div>${d.reference?`<div class="summary-line"><span>Reference</span><span>${esc(d.reference)}</span></div>`:''}<p class="enquiry-message">${esc(d.message)}</p><p class="note">This is a preview only. No message has been sent or stored.</p><button class="btn secondary" onclick="closeModal()">Back to editing</button>`)}
function reviewsPage(){return title('From the crumb community','A few words, a little love.','Share your thoughts on a completed order.')+`<section class="section"><div class="section-head"><h3>Customer reviews <span class="count">${db.reviews.length} reviews</span></h3><button class="btn" onclick="reviewForm()">Write a review</button></div><div class="reviews-grid">${db.reviews.length?db.reviews.map(r=>`<article class="record"><div class="review-stars">${'★'.repeat(Number(r.rating))}${'☆'.repeat(5-Number(r.rating))}</div><h3>${esc(r.title)}</h3><p>${esc(r.comment)}</p><p class="muted">${esc(r.name)} · ${esc(r.order)}</p><div class="record-actions"><button class="btn secondary" onclick="reviewForm('${r.id}')">Edit</button><button class="btn secondary" onclick="deleteEntity('reviews','${r.id}')">Delete</button></div></article>`).join(''):empty('Be the first to share','Reviews become available when an order is marked Completed.','#orders','View my orders')}</div></section>`}
function reviewForm(rid=null,oid=''){const r=db.reviews.find(x=>x.id===rid);const completed=db.orders.filter(o=>o.status==='Completed');if(!r&&!completed.length){toast('Complete an order first. Its status can be changed in the admin demo.');return}modal(`<h2>${r?'Edit your':'Write a'} review</h2><form onsubmit="saveReview(event,'${rid||''}')"><div class="form-grid">${select('Order','order',r?[r.order]:completed.map(o=>o.id),r?.order||oid)}${select('Rating','rating',['5','4','3','2','1'],String(r?.rating||5))}${input('Review title','title',r?.title||'')}${area('Your experience','comment',r?.comment||'')}</div><div class="form-actions"><button class="btn">Save review</button></div></form>`)}
function saveReview(e,rid){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.comment.trim()){toast('Please write a few words about your experience');return}const old=db.reviews.find(r=>r.id===rid);old?Object.assign(old,d):db.reviews.push({...d,id:id('REV'),name:profile()?.name||'Guest'});closeModal();location.hash='reviews';render();toast('Review saved')}
const labels={products:'Products',customers:'Users',cakes:'Custom cakes',orders:'Orders',bookings:'Bookings',payments:'Payments',reviews:'Reviews'};
function adminRows(){return db[adminTab].filter(r=>JSON.stringify(r).toLowerCase().includes(adminQuery.toLowerCase())).map(r=>{const status=adminTab==='products'?(productIsSoldOut(r)?'Sold out':'Available'):(r.status||r.type||'Published');const orderActions=adminTab==='orders'?`<button class="btn secondary" onclick="editOrder('${r.id}')">Edit</button><button class="btn secondary" onclick="statusForm('${r.id}')">Update status</button><button class="btn secondary" onclick="orderFeedbackForm('${r.id}')">Feedback</button>${!['Completed','Cancelled'].includes(status)?`<button class="btn complete-action" onclick="setOrderStatus('${r.id}','Completed')">Complete</button>`:''}`:`<button class="btn secondary" onclick="editEntity('${adminTab}','${r.id}')">Edit</button>`;const feedback=r.adminFeedback?`<small class="table-note">Feedback saved</small>`:'';const detail=adminTab==='products'?(r.category||'—'):(r.category||r.date||r.email||r.flavour||r.rating||'—');const stockInfo=adminTab==='products'?`<small class="table-note">${productStock(r)} in stock${r.manualSoldOut?' · manual sold out':''}</small>`:'';return `<tr><td>${esc(r.id)}</td><td>${esc(r.name||r.item||r.title||r.occasion||r.order||(r.items?r.items.map(c=>c.name).join(', '):r.customer)||'—')}</td><td>${esc(detail)}${stockInfo}${feedback}</td><td>${badge(status)}</td><td>${r.price||r.total||r.amount?money(r.price||r.total||r.amount):'—'}</td><td>${orderActions}<button class="btn secondary" onclick="deleteEntity('${adminTab}','${r.id}')">Delete</button></td></tr>`}).join('')}
function adminPage(){return `<div class="admin-route-bar"><div><span class="eyebrow">Private area</span><strong>Owner dashboard</strong></div><div class="admin-route-actions"><span class="owner-badge">ADMIN</span><button class="btn secondary" onclick="signOut()">Sign out</button></div></div>`+title('Owner workspace','Bakery control room','Manage products, users, orders, bookings, payments and customer feedback.')+`<section class="section"><div class="owner-bar"><div><span class="eyebrow">Owner access</span><strong>Everything behind the counter, in one place.</strong><p class="muted">Create, update and delete demo records. Order updates can unlock customer reviews.</p></div><span class="owner-badge">OWNER DEMO</span></div><div class="metrics"><div class="metric">Bakery products<strong>${db.products.length}</strong></div><div class="metric">Users<strong>${db.customers.length}</strong></div><div class="metric">Active orders<strong>${db.orders.filter(o=>!['Completed','Cancelled'].includes(o.status)).length}</strong></div><div class="metric">Open feedback<strong>${db.orders.filter(o=>!o.adminFeedback&&!['Cancelled'].includes(o.status)).length}</strong></div></div><p class="note admin-hint">Admin demo · This workspace is open for project demonstration. Real owner permissions, Java file handling, validation and permanent storage require the backend.</p><div class="chips admin-tabs">${Object.entries(labels).map(([k,v])=>`<button class="chip ${k===adminTab?'active':''}" onclick="adminTab='${k}';adminQuery='';render()">${v}</button>`).join('')}</div><div class="toolbar"><div><h3>${labels[adminTab]}</h3>${adminTab==='orders'?'<p class="muted admin-hint-inline">Use Update status or Complete to move an order through the bakery. Use Feedback to leave a note for the customer.</p>':''}</div><div class="inline-actions"><input class="search" aria-label="Search admin records" placeholder="Search by ID, name, date…" value="${esc(adminQuery)}" oninput="adminQuery=this.value;document.querySelector('#admin-rows').innerHTML=adminRows()"><button class="btn" onclick="adminCreate()">+ Add ${adminTab==='products'?'product':adminTab==='customers'?'user':adminTab==='cakes'?'request':adminTab==='orders'?'order':'record'}</button></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Name / Reference</th><th>Details</th><th>Status</th><th>Amount</th><th>Owner actions</th></tr></thead><tbody id="admin-rows">${adminRows()}</tbody></table></div>${!db[adminTab].length?'<p class="muted">No records yet. Add a record or try the customer journey.</p>':''}</section>`}
function adminCreate(){if(adminTab==='orders'){location.hash='shop';toast('Add products to the bag to create a customer order');return}if(adminTab==='cakes'){location.hash='cakes';return}if(adminTab==='reviews'){reviewForm();return}editEntity(adminTab)}
function editEntity(type,rid=''){const r=db[type].find(x=>x.id===rid)||{};let fields='';if(type==='products')fields=input('Product name','name',r.name)+select('Category','category',['Bread','Pastries','Cakes'],r.category)+input('Price (Rs.)','price',r.price||450,'number')+input('Quantity in stock','quantity',r.quantity??10,'number')+select('Availability','availability',['Available','Sold out'],r.availability)+area('Description','description',r.description);if(type==='customers')fields=input('Name','name',r.name)+input('Email','email',r.email,'email')+input('Phone','phone',r.phone,'tel')+select('Customer type','type',['Regular','Premium'],r.type)+area('Address','address',r.address);if(type==='cakes')fields=select('Occasion','occasion',['Birthday','Wedding','Celebration'],r.occasion)+select('Size','size',['1 kg · 8–10 servings','2 kg · 16–20 servings','3 kg · 24–30 servings'],r.size)+select('Flavour','flavour',['Chocolate','Vanilla','Red velvet','Coffee'],r.flavour)+select('Toppings','toppings',['Chocolate curls','Fresh fruit','Buttercream flowers','No toppings'],r.toppings)+input('Cake message','message',r.message,'text',false)+input('Requested date','date',r.date,'date')+select('Status','status',['Requested','Confirmed','Preparing','Completed','Cancelled'],r.status)+area('Design','design',r.design);if(type==='bookings')fields=input('Booking item','item',r.item)+input('Customer ID','customer',r.customer||'C001')+input('Date','date',r.date,'date')+select('Method','method',['Pickup','Delivery'],r.method)+select('Status','status',['Requested','Confirmed','Preparing','Ready','Completed','Cancelled'],r.status)+area('Delivery address','address',r.address)+area('Instructions','instructions',r.instructions);if(type==='payments')fields=input('Order ID','order',r.order)+input('Amount (Rs.)','amount',r.amount||0,'number')+select('Method','method',['Cash on pickup / delivery','Card payment demo'],r.method)+select('Status','status',['Pending','Simulated paid','Refund pending (demo)','Cancelled'],r.status)+input('Date','date',r.date||new Date().toISOString().slice(0,10),'date');if(type==='reviews'){reviewForm(rid);return}modal(`<h2>${rid?'Edit':'Add'} ${labels[type].toLowerCase()}</h2><form onsubmit="saveEntity(event,'${type}','${rid}')"><div class="form-grid">${fields}</div><div class="form-actions"><button class="btn">Save changes</button><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button></div></form>`)}
function saveEntity(e,type,rid){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.method==='Delivery'&&!d.address?.trim()){toast('Add a delivery address');return}if(type==='payments'&&!db.orders.some(o=>o.id===d.order)){toast('Use an existing order ID');return}let r=db[type].find(x=>x.id===rid);if(r)Object.assign(r,d);else{r={...d,id:id(type.slice(0,2).toUpperCase())};db[type].push(r)}if(type==='products'){r.price=Number(r.price);r.quantity=Math.max(0,Number(d.quantity??0));r.manualSoldOut=d.availability==='Sold out';r.availability=r.manualSoldOut||r.quantity===0?'Sold out':'Available';r.image=images[r.category]}if(type==='payments')r.amount=Number(r.amount);if(type==='cakes'){r.price=4200+(parseInt(r.size)-1)*3000;db.bookings.filter(b=>b.cakeId===rid).forEach(b=>Object.assign(b,{item:`${r.occasion} cake · ${r.flavour}`,date:r.date,status:r.status,total:r.price+(b.method==='Delivery'?350:0)}))}if(type==='bookings'){if(r.cakeId){const c=db.cakes.find(c=>c.id===r.cakeId);if(c){c.date=r.date;c.status=r.status;r.total=c.price+(r.method==='Delivery'?350:0)}}if(r.orderId){const o=db.orders.find(o=>o.id===r.orderId);if(o){Object.assign(o,{date:r.date,method:r.method,address:r.address,status:r.status});o.total=o.items.reduce((n,c)=>n+c.qty*c.price,0)+(r.method==='Delivery'?350:0);r.total=o.total;db.payments.filter(p=>p.order===o.id).forEach(p=>p.amount=o.total)}}}closeModal();render();toast('Changes saved')}
function syncOrderStatus(order,status){order.status=status;if(status==='Completed')order.completedAt=today();db.bookings.filter(b=>b.orderId===order.id).forEach(b=>b.status=status)}
function statusForm(oid){const o=db.orders.find(o=>o.id===oid);modal(`<span class="eyebrow">Owner action · ${esc(oid)}</span><h2>Move this order forward</h2><p class="muted">The customer sees the updated status in My orders.</p><form onsubmit="event.preventDefault();setOrderStatus('${oid}',this.status.value)">${select('Order status','status',['Confirmed','Preparing','Ready','Completed','Cancelled'],o.status)}${o.status!=='Completed'?'<p class="note">Marking an order Completed unlocks its customer review form.</p>':''}<div class="form-actions"><button class="btn">Save status</button></div></form>`)}
function setOrderStatus(oid,status){if(status==='Cancelled'){confirmCancel('orders',oid);return}const o=db.orders.find(o=>o.id===oid);if(!o)return;syncOrderStatus(o,status);closeModal();render();toast(status==='Completed'?'Order completed; customer review unlocked':'Order status updated')}
function orderFeedbackForm(oid){const o=db.orders.find(o=>o.id===oid);if(!o)return;modal(`<span class="eyebrow">Owner feedback · ${esc(oid)}</span><h2>Leave a note for the customer.</h2><p class="muted">Share a pickup update, delivery detail, or a quick thank-you.</p><form onsubmit="saveOrderFeedback(event,'${oid}')"><div class="form-grid">${select('Order status','status',['Confirmed','Preparing','Ready','Completed','Cancelled'],o.status)}${area('Message from Crumb','adminFeedback',o.adminFeedback||'')}</div><p class="note">This demo shows the note in the customer’s order details. A backend notification service can send it later.</p><div class="form-actions"><button class="btn">Save feedback</button></div></form>`)}
function saveOrderFeedback(e,oid){e.preventDefault();const o=db.orders.find(o=>o.id===oid),d=Object.fromEntries(new FormData(e.target));if(!d.adminFeedback?.trim()){toast('Add a short customer note first');return}syncOrderStatus(o,d.status);o.adminFeedback=d.adminFeedback.trim();closeModal();render();toast(d.status==='Completed'?'Order completed and feedback saved':'Order feedback saved')}
function deleteCustomerAccount(rid){
  modal(`<div class="auth-dialog"><span class="eyebrow">Account safety</span><h2 id="delete-title">Delete your profile?</h2><p class="muted">To permanently delete your profile, please enter your password to verify your identity.</p><form class="auth-form" onsubmit="confirmCustomerDelete(event,'${rid}')"><div class="form-grid"><label class="password-label">Enter password<span class="password-input"><input type="password" name="password" required minlength="6" autocomplete="current-password" placeholder="Your password"><button type="button" class="password-toggle" aria-label="Show password" aria-pressed="false" onclick="togglePassword(this)">Show</button></span></label></div><p id="delete-error" class="auth-error" role="alert"></p><div class="form-actions" style="margin-top:16px"><button class="btn danger" type="submit">Delete profile</button><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button></div></form></div>`);
  const dialog=$('#dialog');if(dialog){dialog.classList.add('auth-glass');dialog.setAttribute('aria-labelledby','delete-title');dialog.addEventListener('close',()=>{dialog.classList.remove('auth-glass');dialog.removeAttribute('aria-labelledby')},{once:true});}
}
async function confirmCustomerDelete(e,rid){
  e.preventDefault();
  const d=Object.fromEntries(new FormData(e.target));
  const pwd=(d.password||'').trim();
  const error=$('#delete-error');
  if(!pwd){
    if(error)error.textContent='Please enter your password.';
    return;
  }
  try{
    const res=await fetch('/api/users/'+encodeURIComponent(rid)+'?password='+encodeURIComponent(pwd),{method:'DELETE'});
    const json=await res.json();
    if(!res.ok||!json.success){
      if(error)error.textContent=json.message||'Incorrect password. Account deletion denied.';
      else toast(json.message||'Incorrect password. Account deletion denied.');
      return;
    }
  }catch(_){
    if(error)error.textContent='Could not reach server. Please try again.';
    return;
  }
  db.customers=db.customers.filter(r=>r.id!==rid);
  signOut();
  closeModal();
  render();
  toast('Account deleted successfully');
}
function deleteEntity(type,rid){
  const curr=currentUser()||profile();
  if(type==='customers'&&curr?.id===rid){
    deleteCustomerAccount(rid);
    return;
  }
  modal(`<h2>Delete this record?</h2><p>${esc(rid)} will be removed from this demo. ${type==='orders'?'Its linked bookings and payment records will also be removed.':''}</p><div class="form-actions"><button class="btn danger" onclick="confirmDelete('${type}','${rid}')">Delete record</button><button class="btn secondary" onclick="closeModal()">Keep record</button></div>`);
}
async function confirmDelete(type,rid){
  if(type==='customers'){
    try{
      const res=await fetch('/api/users/'+encodeURIComponent(rid),{method:'DELETE'});
      if(!res.ok){
        toast('Failed to delete user from database');
      }
    }catch(_){}
    const curr=currentUser()||profile();
    if(curr?.id===rid){
      signOut();
    }
  }
  db[type]=db[type].filter(r=>r.id!==rid);
  if(type==='orders'){db.bookings=db.bookings.filter(b=>b.orderId!==rid);db.payments=db.payments.filter(p=>p.order!==rid);db.reviews=db.reviews.filter(r=>r.order!==rid)}
  if(type==='cakes')db.bookings=db.bookings.filter(b=>b.cakeId!==rid);
  closeModal();render();toast('Record deleted from database');
}
function render(){const requested=location.hash.replace(/^#/,'')||'shop';if(requested==='admin'&&!isAdmin()){document.body.classList.remove('admin-mode');if(location.hash!=='#shop'){location.hash='shop';toast('Owner sign-in is required for this area')}return}if(isAdmin()&&requested!=='admin'){document.body.classList.add('admin-mode');if(location.hash!=='#admin')location.hash='admin';return}const route=requested;document.body.classList.toggle('admin-mode',route==='admin'&&isAdmin());updateAuthHeader();const pages={shop,cakes:cakePage,cart:cartPage,orders:ordersPage,bookings:bookingsPage,account:accountPage,reviews:reviewsPage,contact:contactPage,admin:adminPage};$('#app').innerHTML=(pages[route]||shop)();$('nav').querySelectorAll('a').forEach(a=>{const active=a.hash==='#'+route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.syncNavIndicator?.();const count=String(cart.reduce((n,c)=>n+c.qty,0));if($('#cart-count').textContent!==count)$('#cart-count').textContent=count;if(route==='cart'&&cart.length){const el=$('select[name=method]');el.addEventListener('change',()=>$('#checkout-total').textContent=money(totals().sub+(el.value==='Delivery'?350:0)))}}
// Animate only page content so the live header and its indicator stay uninterrupted.
let pageMotion=null;
function navigatePage(){
  pageMotion?.cancel();
  render();window.scrollTo({top:0,left:0,behavior:'instant'});
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  if(typeof $('#app').animate==='function')pageMotion=$('#app').animate([{transform:'translateY(6px)'},{transform:'translateY(0)'}],{duration:180,easing:'cubic-bezier(.2,.7,.2,1)'});
}
window.addEventListener('hashchange',navigatePage);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'search_bakery_products',title:'Search bakery products',description:'Read matching products, prices and availability from the current bakery catalogue.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(typeof input?.query!=='string')throw Error('query must be a string');return db.products.filter(p=>`${p.name} ${p.category} ${p.id}`.toLowerCase().includes(input.query.toLowerCase())).map(p=>({id:p.id,name:p.name,price:p.price,quantity:productStock(p),availability:productStockLabel(p)}))}});register({name:'add_bakery_product_to_bag',title:'Add a product to bag',description:'Add one available product to the visible shopping bag. Does not place an order.',inputSchema:{type:'object',properties:{productId:{type:'string'}},required:['productId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.productId!=='string')throw Error('productId must be a string');const result=addToCart(input.productId);if(location.hash==='#cart')render();return result}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
